unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  return (log(x));
}

path foo = graph(func,exp(-5),5); 

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
